CREATE TABLE organizations(id text PRIMARY KEY,name text NOT NULL,provider_mode text NOT NULL DEFAULT 'healthy');
CREATE TABLE users(id text PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,password_hash text NOT NULL,salt text NOT NULL,credential_version integer NOT NULL DEFAULT 1);
CREATE TABLE memberships(org_id text REFERENCES organizations(id),user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('maker','checker','admin','viewer')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(token text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),org_id text NOT NULL REFERENCES organizations(id),credential_version integer NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE beneficiaries(id text NOT NULL,org_id text NOT NULL REFERENCES organizations(id),name text NOT NULL,bank text NOT NULL,account_suffix text NOT NULL,category text NOT NULL,PRIMARY KEY(org_id,id));
CREATE TABLE payments(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),beneficiary_id text NOT NULL,amount bigint NOT NULL CHECK(amount BETWEEN 1 AND 9999999999),reference text NOT NULL,status text NOT NULL CHECK(status IN ('pending','queued','retrying','reconciling','paid','declined','failed','rejected')),created_by text NOT NULL REFERENCES users(id),reviewed_by text REFERENCES users(id),reason text,receipt text,version integer NOT NULL DEFAULT 1,created_at bigint NOT NULL,updated_at bigint NOT NULL,trace_context jsonb NOT NULL DEFAULT '{}',UNIQUE(org_id,id),FOREIGN KEY(org_id,beneficiary_id) REFERENCES beneficiaries(org_id,id),CHECK(reviewed_by IS NULL OR reviewed_by <> created_by));
CREATE TABLE audit(id bigserial PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),payment_id text,actor text NOT NULL,action text NOT NULL,detail text NOT NULL,request_id text,created_at bigint NOT NULL,FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id));
CREATE TABLE idempotency(org_id text NOT NULL,actor text NOT NULL,key text NOT NULL,fingerprint text NOT NULL,payment_id text NOT NULL,PRIMARY KEY(org_id,actor,key),FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id));
CREATE TABLE jobs(payment_id text PRIMARY KEY REFERENCES payments(id),org_id text NOT NULL REFERENCES organizations(id),attempts_cycle integer NOT NULL DEFAULT 0,next_at bigint NOT NULL,done boolean NOT NULL DEFAULT false,uncertain boolean NOT NULL DEFAULT false,lease_owner text,lease_until bigint,claim_version integer NOT NULL DEFAULT 0,last_error text,FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id));
CREATE TABLE attempts(id bigserial PRIMARY KEY,org_id text NOT NULL,payment_id text NOT NULL,worker text NOT NULL,claim_version integer NOT NULL,operation text NOT NULL,outcome text NOT NULL,detail text NOT NULL,request_id text NOT NULL,provider_request_id text,started_at bigint NOT NULL,finished_at bigint NOT NULL,stale boolean NOT NULL DEFAULT false,FOREIGN KEY(org_id,payment_id) REFERENCES payments(org_id,id));
CREATE TABLE throttle(key text PRIMARY KEY,count integer NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE invitations(token text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('maker','checker','admin','viewer')),expires_at bigint NOT NULL,used_at bigint);
CREATE TABLE recoveries(token text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires_at bigint NOT NULL,used_at bigint);
CREATE TABLE delivery_outbox(id bigserial PRIMARY KEY,recipient text NOT NULL,kind text NOT NULL,payload text NOT NULL,created_at bigint NOT NULL);
CREATE TABLE worker_heartbeats(worker text PRIMARY KEY,seen_at bigint NOT NULL);
CREATE TABLE callback_events(id text PRIMARY KEY,created_at bigint NOT NULL);
CREATE TABLE audit_exports(destination text PRIMARY KEY,last_id bigint NOT NULL DEFAULT 0);
CREATE INDEX payments_created ON payments(org_id,created_at DESC,id DESC);
CREATE INDEX payments_status ON payments(org_id,status,created_at DESC,id DESC);
CREATE INDEX payments_amount ON payments(org_id,amount DESC,id DESC);
CREATE INDEX audit_org ON audit(org_id,id DESC);
CREATE INDEX audit_payment ON audit(org_id,payment_id,id DESC);
CREATE INDEX attempts_payment ON attempts(org_id,payment_id,id DESC);
CREATE INDEX jobs_due ON jobs(next_at) WHERE done=false;
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE FUNCTION prevent_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END; $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
CREATE TRIGGER immutable_attempts BEFORE UPDATE OR DELETE ON attempts FOR EACH ROW EXECUTE FUNCTION prevent_history_change();
